mapper.select:
	SELECT T.notice_id, T.title, T.category_cd, U.user_name, T.create_dt, T.view_count, T.del_yn, C.code_name AS categoryName
	FROM t3000_notice T
	JOIN T1000_account  A ON COALESCE(T.update_Id, T.create_id) = A.account_id
	JOIN t1000_user U ON A.user_no = U.user_no
	JOIN total_code C ON T.category_cd = C.code_id
	JOIN t2000_complain_category CC ON T.category_cd = CC.category_cd
	WHERE T.del_yn = 'N'

				AND T.title = #{title}


				AND U.user_name = #{userName}


				AND C.code_name = #{categoryName}


				AND CC.complain_category_id = #{complainCategoryId}



					AND T.create_dt >= TO_DATE(#{startDate},
					'YYYY-MM-DD')
					AND T.create_dt < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1





    WHERE RNUM BETWEEN #{startRow} AND #{endRow}

	ORDER BY T.create_dt DESC

SELECT COUNT(*) FROM t3000_notice T JOIN T1000_account A ON COALESCE(T.update_Id, T.create_id) = A.account_id JOIN t1000_user U ON A.user_no = U.user_no JOIN total_code C ON T.category_cd = C.code_id JOIN t2000_complain_category CC ON T.category_cd = CC.category_cd WHERE T.del_yn = 'N'
AND T.title = #{title}
AND U.user_name = #{userName}
AND C.code_name = #{categoryName}
AND CC.complain_category_id = #{complainCategoryId}
AND T.create_dt >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND T.create_dt < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1

mapper.insert:
	INSERT INTO t3000_notice (
	title, create_id, create_dt, content, category_cd, popup_yn
	)
	values(
	#{title},#{createId}, SYSDATE, #{content}, 
	 #{categoryCd}
     NULL,
	#{popupYn}
	)

mapper.update:
UPDATE t3000_notice
SET del_yn = 'Y'
WHERE notice_id= #{noticeId}

UPDATE t3000_notice
SET view_count = view_count + 1
WHERE notice_id = #{noticeId}
